/// <summary>
/// VendInvoiceInfoTable table extension
/// </summary>
[ExtensionOf(tableStr(VendInvoiceInfoTable))]
final class METVendInvoiceInfoTable_Extension
{
}

Method.Source:
    public boolean canSubmitToWorkflow(str workflowType)
    {
        boolean ret = next canSubmitToWorkflow(workflowType);

        ret = ret && this.metCheckInvoice();

        return ret;
    }

    /// <summary>
    /// calculate markup totals
    /// </summary>
    /// <returns>totals container</returns>
    public container metMarkupTotals()
    {
        VendInvoiceInfoLine metVendInvoiceInfoLine;
        MarkupTrans         metMarkupTrans;
        Amount              metTotalTaxAmount, metTotalAmount, metAmount;

        while select metMarkupTrans
            join metVendInvoiceInfoLine
                where metMarkupTrans.TransTableId          == tableNum(VendInvoiceInfoLine) &&
                      metMarkupTrans.TransRecId            == metVendInvoiceInfoLine.RecId &&
                      // Bug 350958: E2E: SO-0237 - Wrong amount posting to In-Tolerance Variance Line Unit Price & Actual GST
                      // ParmId is blank when PVI is closed, a new ParmId is generated everytime a user opens the PVI
                      // This is to handle scenario when user open the PVI when the workflow is executing
                      //metVendInvoiceInfoLine.ParmId        == this.ParmId &&
                      metVendInvoiceInfoLine.TableRefId    == this.TableRefId
        {
            metAmount = Markup::calcMarkupAmount(metMarkupTrans, metVendInvoiceInfoLine.ReceiveNow, metVendInvoiceInfoLine.LineAmount, 0,
                metVendInvoiceInfoLine.inclTax(), NoYes::Yes, metMarkupTrans.CurrencyCode, metMarkupTrans.TransDate,
                                     0, 0, null, false, 0, '', false, false);

            TransDate transDate = metMarkupTrans.TransDate ? metMarkupTrans.TransDate : DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

            metTotalTaxAmount  += Tax::calcTaxAmount(metMarkupTrans.TaxGroup, metMarkupTrans.TaxItemGroup, transDate,
                metMarkupTrans.CurrencyCode, metAmount, TaxModuleType::PurchInvoice);

            metTotalAmount += metAmount;
        }

        return [metTotalAmount, metTotalTaxAmount];
    }

    /// <summary>
    /// Check Invoice method extension
    /// </summary>
    /// <param name = "_ledgerJournalTrans"><c>LedgerJournalTrans</c> buffer.</param>
    /// <returns>True if invoice is not found; otherwise false</returns>
    boolean metCheckInvoice()
    {
        boolean ret = true;

        if (VendParameters::find().CheckInvoice == ReuseVoucher::METInvoiceValidation)
        { 
            ret = ret && this.metCheckPendingVendorInvoice();
        }

        return ret;
    }

    /// <summary>
    /// Apply metcash invoice number duplicate check. 
    /// </summary>
    /// <returns>true, if the invoice number is not duplicate otherwise false</returns>
    boolean metCheckPendingVendorInvoice()
    {
        VendInvoiceInfoTable infoTable;
        boolean ret = true;
        // for existing invoices
        AmountCur invAmount = this.displayInvoiceAmountExclGST();
        // non posted invoices
        while select infoTable
            where infoTable.Num == this.Num 
                && infoTable.RecId != this.RecId
        {
            if(infoTable.displayInvoiceAmountExclGST() == invAmount)
            {
                if (infoTable.InvoiceAccount == this.InvoiceAccount)//vendor
                {
                    return checkFailed(strFmt("@MET:METInvoiceWithAmountAlreadyUsedForVendor", this.Num, invAmount, date2StrUsr(infoTable.DocumentDate, DateFlags::FormatAll), this.InvoiceAccount));
                }
                else if (infoTable.DocumentDate == this.DocumentDate)
                {
                    return checkFailed(strFmt("@MET:METInvoiceWithmountAlreadyUsedOnDate", this.Num, invAmount, date2StrUsr(infoTable.DocumentDate, DateFlags::FormatAll)));
                }
            }
        }

        if (ret)
        {
            VendInvoiceJour invJour;
            // for posted invoices.
            select firstonly RecId from invJour
                where invJour.InvoiceId == this.Num
                    && invJour.InvoiceAccount == this.InvoiceAccount 
                    && invJour.SalesBalance == invAmount;
            
            if (invJour)
            {
                ret = checkFailed(strFmt("@MET:METInvoiceWithAmountAlreadyUsedForVendor", this.Num, invAmount, date2StrUsr(invJour.DocumentDate, DateFlags::FormatAll), this.InvoiceAccount));
            }
            else
            {
                select firstonly RecId from invJour
                    where invJour.InvoiceId == this.Num
                        && invJour.DocumentDate == this.DocumentDate
                        && invJour.SalesBalance == invAmount;

                if (invJour)
                {
                    ret = checkFailed(strFmt("@MET:METInvoiceWithmountAlreadyUsedOnDate", this.Num, invAmount, date2StrUsr(invJour.DocumentDate, DateFlags::FormatAll)));
                }
            }
        }

        return ret;
    }

    public boolean validateWrite()
    {
        boolean isValid = next validateWrite();

        isValid = isValid && this.metCheckInvoice();

        return isValid;
    }

    /// <summary>
    /// Line amounts
    /// </summary>
    /// <returns>line amounts</returns>
    public container metlineAmounts()
    {
        PurchTotals     metPurchTotals;

        metPurchTotals = PurchTotals::newParmTable(this, PurchUpdate::All, this.ParmId, '', this.Ordering);
        metPurchTotals.calc();

        return [metPurchTotals.purchBalance(), metPurchTotals.purchTaxTotal()];
    }

    /// <summary>
    /// Display method to calculate GST variance
    /// </summary>
    /// <returns>GST variance</returns>
    public display MetGSTVariance displayMetGSTVariance()
    {
        Amount metTotalMarkupTax, metTotalMarkupAmount;
        Amount metTotalLineTax, metTotalLineAmount;

        [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
        [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

        return this.MetImportGST - (metTotalLineTax - metTotalMarkupTax);
    }

    /// <summary>
    /// Display method to calculate variance
    /// </summary>
    /// <returns>Variance</returns>
    public display MetVariance displayMetVariance()
    {
        Amount metTotalMarkupTax, metTotalMarkupAmount;
        Amount metTotalLineTax, metTotalLineAmount;

        [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
        [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

        return this.MetImportAmount - (metTotalLineAmount + (metTotalLineTax - metTotalMarkupTax));
    }

    /// <summary>
    /// Variance tolerance
    /// </summary>
    /// <returns>tolerance</returns>
    public display MetVarInTol displayMETVarInTolerance()
    {
        METVendParameters metVendParameters = METVendParameters::find();
        MetVariance metVariance = this.displayMetVariance();

        Amount metTotalMarkupTax, metTotalMarkupAmount;
        Amount metTotalLineTax, metTotalLineAmount;

        [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
        [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

        METTaxInvTotalsToleranceDollar taxInvTotalsToleranceDollar = metVendParameters.TaxInvTotalsToleranceDollar;
        Amount InvTotalPercAmt = (metVendParameters.TotalPriceTolerancePercentage * (metTotalLineAmount + (metTotalLineTax - metTotalMarkupTax))) / 100;

        return abs(metVariance) && abs(metVariance) <= taxInvTotalsToleranceDollar && abs(metVariance) <= InvTotalPercAmt;
    }

    /// <summary>
    /// Finds claim lines
    /// </summary>
    /// <returns>True if claim line exists; otherwise false</returns>
    public display MetClaimExist displayMETHasClaimLines()
    {
        VendInvoiceInfoLine metVendInvoiceInfoLine;

        select count(RecId) from metVendInvoiceInfoLine
            where
                metVendInvoiceInfoLine.ParmId          == this.ParmId &&
                metVendInvoiceInfoLine.TableRefId      == this.TableRefId &&
                metVendInvoiceInfoLine.MetClaimLine    == NoYes::Yes;

        return metVendInvoiceInfoLine.RecId > 0;
    }

/// <summary>
/// CB411_412_ChargeThrough
/// </summary>
/// <param name = "_vendTable"><c>VendTable</c> record to initialise fields from.</param>
void METInitFromVendTable(VendTable _vendTable)
{
    this.OrderAccount           = _vendTable.AccountNum;
    this.InvoiceAccount         = _vendTable.AccountNum;
    this.InclTax                = _vendTable.InclTax;
}

/// <summary>
/// CB411_412_ChargeThrough
/// </summary>
/// <param name = "_metVendTable"><c>METVendTable</c> record to initialise fields from.</param>
void METInitFromMETVendTable(METVendTable _metVendTable)
{
    this.METCBCTWarehouseVendor = _metVendTable.CBCTWarehouseVendor;
}

    /// <summary>
    /// CB411_412_ChargeThrough
    /// </summary>
    /// <param name = "_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c> record to initialise fields from.</param>
    void METInitFromCBCTInvoiceHeaderTable(METCBCTInvoiceHeaderTable _cbCTInvoiceHeaderTable)
    {
        this.DocumentDate           = _cbCTInvoiceHeaderTable.DocumentDate;        
        this.CurrencyCode           = _cbCTInvoiceHeaderTable.CurrencyCode;
        this.TransDate              = _cbCTInvoiceHeaderTable.TransactionDate;
        this.Num                    = _cbCTInvoiceHeaderTable.TaxInvoiceNum;
        this.CashDiscCode           = VendTable::find(this.OrderAccount).CashDisc;

        this.FixedDueDate           = _cbCTInvoiceHeaderTable.VendDueDate;
        this.MetImportAmount        = _cbCTInvoiceHeaderTable.VendInvoiceAmtInclGST;
        this.MetImportGST           = _cbCTInvoiceHeaderTable.VendInvoiceGSTAmount;
        this.METCBCTNumber          = _cbCTInvoiceHeaderTable.Number;
        this.Description            = _cbCTInvoiceHeaderTable.TaxInvoiceNum;
        this.METSkipInvoiceMatching = NoYes::Yes;
        this.METCBCTWarehouseVendor = NoYes::No;
        this.DefaultDimension       = _cbCTInvoiceHeaderTable.FinancialDimension;

        if (_cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::ChargeThrough)
        {
            this.METChargeThrough  = NoYes::Yes;
        }
        
        if (_cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::CrossDock)
        {
            this.METCrossDock      = NoYes::Yes;
        }

        if (_cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::RDA)
        {
            this.METRDA = NoYes::Yes;
        }
    }

    /// <summary>
    /// Displays the invoice total amount include GST.
    /// </summary>
    /// <returns>Invoice total amount include GST.</returns>
    public display METD365InvoiceTotal displayInvoiceTotal()
    {
        Amount metTotalLineTax, metTotalLineAmount;

        [metTotalLineAmount, metTotalLineTax] = this.metLineAmounts();

        return metTotalLineAmount + metTotalLineTax;
    }

    /// <summary>
    /// Calculates and display match status based on the varaiance and invoice total.
    /// </summary>
    /// <returns>Match status</returns>
    public display METMatchStatus displayMetMatchStatus()
    {
        METMatchStatus matchStatus = METMatchStatus::No;
        METVendParameters metVendParameters = METVendParameters::find();

        if (metVendParameters.EnableMetcashMatchingLogic)
        {
            Amount metTotalMarkupTax, metTotalMarkupAmount;
            Amount metTotalLineTax, metTotalLineAmount;

            [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
            [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

            METTaxInvTotalsToleranceDollar taxInvTotalsToleranceDollar = metVendParameters.TaxInvTotalsToleranceDollar;
            Amount InvTotalPercAmt = (metVendParameters.TotalPriceTolerancePercentage * (metTotalLineAmount + (metTotalLineTax - metTotalMarkupTax))) / 100;
            MetVariance variance = this.MetImportAmount - (metTotalLineAmount + (metTotalLineTax - metTotalMarkupTax));
            MetVariance gstVariance = abs(this.displayMetGSTVariance());

            if (abs(variance) == 0 && abs(gstVariance) == 0)
            {
                matchStatus = METMatchStatus::Pass;
            }
            else
            {
                if (metVendParameters.DisplayTotalPriceMatchIcon == DisplayTotalPriceMatchOption::GreaterThan)
                {
                    if ((variance <= taxInvTotalsToleranceDollar && variance <= InvTotalPercAmt) && (gstVariance <= taxInvTotalsToleranceDollar && gstVariance <= InvTotalPercAmt))
                    {
                        matchStatus = METMatchStatus::Pass;
                    }
                    else
                    {
                        matchStatus = METMatchStatus::Fail;
                    }
                }
                else if (metVendParameters.DisplayTotalPriceMatchIcon == DisplayTotalPriceMatchOption::GreaterOrLessThan)
                {
                    if ((abs(variance) + abs(gstVariance)) <= taxInvTotalsToleranceDollar && (abs(variance) + abs(gstVariance)) <= InvTotalPercAmt)
                    {
                        matchStatus = METMatchStatus::Pass;
                    }
                    else
                    {
                        matchStatus = METMatchStatus::Fail;
                    }
                }
            }

            if (this.METEDIInvoice)
            {
                VendInvoiceInfoLine invoiceInfoLine;

                while select ItemId, ReceiveNow, LineAmount, PurchPrice, METReceiptedUnit from invoiceInfoLine
                    where invoiceInfoLine.ParmId == this.ParmId
                    && invoiceInfoLine.TableRefId == this.TableRefId
                {
                    PriceTolerancePercentage percentTolerance = PurchPriceTolerance::find(invoiceInfoLine.ItemId, this.InvoiceAccount);
                    Amount lineVariance = invoiceInfoLine.displayPriceVariance() * invoiceInfoLine.ReceiveNow;
                    Amount InvTotalLinePercAmt = (percentTolerance * invoiceInfoLine.LineAmount) / 100;

                    if (lineVariance > InvTotalLinePercAmt)
                    {
                        return METMatchStatus::Fail;
                    }
                }
            }

            ITMImportCostingVendor importCostingVendor = this.vendTable_InvoiceAccount().ITMImportCostingVendor;

            if (importCostingVendor)
            {
                return METMatchStatus::Pass;
            }
        }

        return matchStatus;
    }

/// <summary>
/// Field will be populated with the difference between invoice total and GST.
/// </summary>
/// <returns>METInvAmtExclGST</returns>
public display METInvAmtExclGST displayInvoiceAmountExclGST()
{
    return this.MetImportAmount - this.MetImportGST;
}

    /// <summary>
    /// Displays the claim invoice number created for this invoice.
    /// </summary>
    /// <returns>METClaimInvoiceNumber</returns>
    public display METClaimInvoiceNumber displayClaimInvoiceNumber()
    {
        METClaimInvoiceNumber claimNumber;
        //409418 - Per request the invoice number length is truncated to 16 characters including the -CR suffix.
        //Instead of first 13 characters we are now taking the last 13 characters of the original invoice number.
        if (this.Num && this.displayMETHasClaimLines())
        {
            int invLength = strLen(this.Num);

            if (invLength > 13)
            {
                int charToTruncate = invLength - 13;
                claimNumber = subStr(this.Num, charToTruncate, 13);
            }

            claimNumber = strFmt("@MET:PlaceHolder", claimNumber, METConstants::VendInvoiceInfoCreditNoteSuffix);
        }

        return claimNumber;
    }

/// <summary>
/// Displays the vendor invoice number for the claim invoice.
/// </summary>
/// <returns>METVendorInvoiceNumber</returns>
public display METVendorInvoiceNumber displayVendorInvoiceNumber()
{
    return  this.METClaimInvoice ? subStr(this.Num, 1, strLen(this.Num)-3) : '';
}

/// <summary>
/// True if charge through or Cross dock or Skip invoice matching check box enabled, otherwise false.
/// </summary>
/// <returns>Bollean value</returns>
public boolean skipCustomInvoiceMatching()
{
    return (this.METCrossDock || this.METChargeThrough || this.METRDA || this.METSkipInvoiceMatching);
}

/// <summary>
/// True if import costing vendor active on Vendor otherwise false.
/// </summary>
/// <returns>Boolean value</returns>
public boolean isLandedCostEnabled()
{
    return VendTable::find(this.InvoiceAccount).ITMImportCostingVendor;
}

    /// <summary>
    /// Bug 275352: CB411- Vendor auto charges not getting copied to sales lines (DIsc1 and Disc2) if created through CT
    /// </summary>
    /// <returns>True if all PVI lines have an off remittance charge code; otherwise, false.</returns>
    public boolean METCheckOffRemittanceChargeCodes()
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;
        boolean ret = true;

        while select vendInvoiceInfoLine        
               where vendInvoiceInfoLine.ParmId == this.ParmId
                  && vendInvoiceInfoLine.TableRefId == this.TableRefId
        {
            if (!vendInvoiceInfoLine.METExistOffRemittanceChargeCode())
            {
                return false;
            }
        }

        return ret;
    }

/// <summary>
/// Bug 410627 Set the EDI GRN status to Waiting when no packing slip is found for an EDI invoice;
/// otherwise, set the status to GRN.
/// </summary>
public void metSetEDIGRNStatus()
{
    if (this.METEDIInvoice)
    {
        if (this.packingSlipId(this))
        {
            this.METEDIGrnStatusValue = METEDIGrnStatus::GRN;
            this.documentDate = VendInvoiceInfoTable::metInvoiceDateForMultipleReceipt(this);
            this.modifiedField(fieldNum(VendInvoiceInfoTable, DocumentDate));
        }
        else
        {
            this.METEDIGrnStatusValue = METEDIGrnStatus::Waiting;
            this.TransDate = dateNull();
            this.DocumentDate = dateNull();
            this.editFixedDueDate(true, dateNull());
        }
    }
}

    /// <summary>
    /// Get the invoice date from the receipts.
    /// </summary>
    /// <param name = "_vendInvoiceInfoTable">VendInvoiceInfoTable</param>
    /// <returns>InvoiceDate</returns>
    public static InvoiceDate metInvoiceDateForMultipleReceipt(VendInvoiceInfoTable _vendInvoiceInfoTable)
    {
        InvoiceDate             invoiceDate;
        VendPackingSlipJour     vendPackingSlipJour;
        VendPackingSlipTrans    vendPackingSlipTrans;
        VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;
        VendInvoiceInfoLine     vendInvoiceInfoLine;

        if (VendParameters::find().METDefaultInvDate)
        {
            select firstonly DeliveryDate from vendPackingSlipJour order by DeliveryDate asc
                exists join vendPackingSlipTrans
                where vendPackingSlipTrans.VendPackingSlipJour == vendPackingSlipJour.RecId
                    exists join VendInvoiceInfoSubLine
                    where VendInvoiceInfoSubLine.JournalRefRecId == vendPackingSlipTrans.RecId
                    && VendInvoiceInfoSubLine.JournalRefTableId == tableNum(VendPackingSlipTrans)
                        exists join vendInvoiceInfoLine
                        where vendInvoiceInfoLine.RecId == VendInvoiceInfoSubLine.LineRefRecId
                        && vendInvoiceInfoLine.ParmId == _vendInvoiceInfoTable.ParmId
                        && vendInvoiceInfoLine.TableRefId == _vendInvoiceInfoTable.TableRefId;

            if (vendPackingSlipJour && vendPackingSlipJour.DeliveryDate != _vendInvoiceInfoTable.DocumentDate)
            {
                invoiceDate = vendPackingSlipJour.DeliveryDate;
            }
        }
        return invoiceDate;
    }
